-- SOLO CI: PostgreSQL aislado con usuarios, cuentas y dinero ficticios.
create extension if not exists pgcrypto;
create role anon;create role authenticated;create role service_role bypassrls;
create schema auth;create schema cc_internal;create schema storage;
create table auth.users(id uuid primary key,email text);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select jsonb_build_object('role',current_setting('request.jwt.claim.role',true))$$;
create table public.cc_admins(user_id uuid primary key references auth.users);
create table public.cc_clan_codes(user_id uuid primary key references auth.users,code text,code_number bigint);
create table public.cc_clan_attributions(referred_user_id uuid primary key references auth.users,inviter_user_id uuid references auth.users,recorded_at timestamptz default now());
create table public.cc_businesses(id uuid primary key default gen_random_uuid(),code text unique);
create table public.cc_memberships(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,business_id uuid references public.cc_businesses,role text,status text,activated_at timestamptz,unique(user_id,business_id));
create table public.cc_plans(id uuid primary key default gen_random_uuid(),business_id uuid references public.cc_businesses,code text,title text,billing_type text,price_pen numeric,is_active boolean,unique(business_id,code));
create table public.cc_subscriptions(id uuid primary key default gen_random_uuid(),membership_id uuid references public.cc_memberships,plan_id uuid references public.cc_plans,status text,start_at timestamptz,end_at timestamptz);
create table public.cc_real_service_wallets(user_id uuid references auth.users,service text,balance_pen numeric not null check(balance_pen>=0),updated_at timestamptz default now(),primary key(user_id,service));
create table public.cc_real_wallet_spends(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,service text,kind text,amount_pen numeric check(amount_pen>0),reference text unique,description text,created_at timestamptz default now());
create table public.cc_real_wallet_refunds(id uuid primary key default gen_random_uuid(),spend_id uuid references public.cc_real_wallet_spends,user_id uuid,service text,amount_pen numeric,reference text unique,reason text,created_at timestamptz default now());
create table public.cc_cobra_real_access_periods(id uuid primary key default gen_random_uuid(),user_id uuid,spend_id uuid references public.cc_real_wallet_spends unique,kind text,period_start timestamptz,period_end timestamptz,status text default 'ACTIVE',amount_pen numeric constraint cc_cobra_real_access_periods_amount_pen_check check(amount_pen=15));
create table public.mc_accounts(user_id uuid primary key references auth.users,subscription_until timestamptz,suspended boolean default false);
create table public.ma_accounts(user_id uuid primary key references auth.users,subscription_until timestamptz,suspended boolean default false);
create table public.mc_subscription_events(id uuid primary key default gen_random_uuid(),request_id uuid unique,reseller_id uuid,paid_with text,amount_pen numeric constraint mc_subscription_events_amount_pen_check check(amount_pen=15),active_until timestamptz,created_at timestamptz default now());
create table public.ma_subscription_events(id uuid primary key default gen_random_uuid(),request_id uuid unique,reseller_id uuid,funding text,amount_pen numeric constraint ma_subscription_events_amount_pen_check check(amount_pen=15),active_until timestamptz,created_at timestamptz default now());
create table public.cc_portal_super_resellers(user_id uuid primary key references auth.users,enabled boolean,admin_percent numeric check(admin_percent between 0 and 100));
create table public.cc_portal_stream_products(id uuid primary key default gen_random_uuid(),seller_id uuid,price_pen numeric);
create table public.cc_portal_stream_orders(id uuid primary key default gen_random_uuid(),checkout_key uuid unique,buyer_id uuid,seller_id uuid,product_id uuid references public.cc_portal_stream_products,service text,title text,price_pen numeric,cost_pen numeric,admin_percent numeric,admin_fee_pen numeric,seller_payable_pen numeric,status text,order_no bigint generated by default as identity(start with 100000),order_code text generated always as ('ORD-'||order_no::text) stored,created_at timestamptz default now());
create table public.cc_cobra_referral_bonuses(id uuid primary key default gen_random_uuid(),beneficiary_user_id uuid,amount_pen numeric,status text);
create table public.cc_real_wallet_ledger(id uuid primary key default gen_random_uuid(),amount_pen numeric);
create table public.cc_admin_verified_personal_topups(id uuid primary key default gen_random_uuid(),credited_pen numeric);
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,unique(bucket_id,name));
alter table storage.objects enable row level security;
create function storage.foldername(text) returns text[] language sql immutable as $$select string_to_array($1,'/')$$;
create function public.cc_refund_verified_real_purchase(p_spend_reference text,p_refund_reference text,p_amount numeric,p_reason text) returns boolean language plpgsql as $$begin
 return true;end;$$;
create function public.cc_refund_cobra_real_subscription(p_access_id uuid,p_refund_reference text,p_reason text) returns boolean language plpgsql as $$begin
 return true;end;$$;
grant usage on schema public,auth,storage to authenticated,anon,service_role;

create table public.cc_wallet_financial_audit(id bigint generated always as identity primary key,user_id uuid,service text,event_type text,concept text,amount_pen numeric,balance_before numeric,balance_after numeric,reference text,related_payment_ref text,referred_user_id uuid,original_reference text,reason text,affects_balance boolean default true);

create table public.cc_portal_stream_memberships_paid(checkout_key uuid primary key,user_id uuid,amount_pen numeric,ends_at timestamptz,membership_id uuid,subscription_id uuid);

alter table public.cc_portal_stream_products add column status text default 'ACTIVE',add column stock integer default 10,add column service text default 'Netflix',add column title text default 'Licencia ficticia',add column distributor_price_pen numeric,add column whatsapp text default '+51900000000',add column cost_pen numeric default 0;
alter table public.cc_portal_stream_orders add column seller_whatsapp text,add column wallet_parts jsonb;
